import type { MoodValue } from './types';

export const MOOD_EMOJIS: Record<MoodValue, string> = {
  1: '🌧️',
  2: '☁️',
  3: '⛅',
  4: '🌤️',
  5: '☀️',
};

export const MOOD_LABELS: Record<MoodValue, string> = {
  1: 'Schlecht',
  2: 'Müde',
  3: 'Neutral',
  4: 'Gut',
  5: 'Ausgezeichnet',
};

export function moodEmoji(value: MoodValue): string {
  return MOOD_EMOJIS[value];
}

export function moodLabel(value: MoodValue): string {
  return MOOD_LABELS[value];
}

import type { Habit } from './types';
import { lastXDays, daysAgo } from './db';

interface StreakResult {
  current: number;
  longest: number;
  dates: string[];
}

/* Simple logic: look back from today, counting consecutively checked days.
 * Returns current streak, longest streak, and the exact dates that are
 * in the streak. */
export function calcStreak(
  checks: Array<{ habitId: string; date: string }>,
  habitId: string
): StreakResult {
  const habitChecks = checks
    .filter((c) => c.habitId === habitId)
    .map((c) => c.date)
    .sort();

  let current = 0;
  let longest = 0;
  let lastToday = 0;

  for (const d of habitChecks) {
    const daysSince = diffDays(d);
    if (daysSince === current + 1 || (current === 0 && daysSince === 0)) {
      if (current + 1 > longest) {
        longest = current + 1;
      }
      current++;
      lastToday = current;
    } else {
      current = 0;
    }
  }

  return {
    current: Math.max(current, lastToday),
    longest,
    dates: [],
  };
}

export function calcDailyStats(
  checks: Array<{ habitId: string; date: string }>
): Record<string, number> {
  const grouped: Record<string, number> = {};
  for (const c of checks) {
    grouped[c.date] = (grouped[c.date] || 0) + 1;
  }
  return grouped;
}

function diffDays(dateStr: string): number {
  const today = new Date(todayNormalized());
  const target = new Date(dateStr);
  const diff = (today.getTime() - target.getTime()) / 86400000;
  return Math.round(diff);
}

function todayNormalized(): string {
  return new Date().toISOString().slice(0, 10);
}

import { useState, useEffect } from 'react';
import {
  getHabits,
  getChecksForDate,
  checkHabit,
  uncheckHabit,
  today,
  formatDate,
} from '../lib/db';
import type { Habit } from '../lib/types';
import { IconCheck } from '../icons';

export function Today() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [checked, setChecked] = useState<Set<string>>(new Set());
  const date = today();
  const label = formatDate(new Date(date));

  useEffect(() => {
    (async () => {
      const h = await getHabits();
      const c = await getChecksForDate(date);
      setHabits(h);
      setChecked(new Set(c));
    })();
  }, [date]);

  const done = checked.size;

  async function toggle(id: string) {
    const next = new Set(checked);
    const was = next.has(id);
    if (was) {
      next.delete(id);
      await uncheckHabit(id, date);
    } else {
      next.add(id);
      await checkHabit(id, date);
    }
    setChecked(next);
  }

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <p className="text-[13px] uppercase tracking-[0.08em] font-medium text-neutral-500 mb-1">
        {label}
      </p>
      {habits.length > 0 && (
        <p className="text-[13px] text-neutral-500 mb-5">
          {done} von {habits.length} erledigt
        </p>
      )}
      {habits.length === 0 && (
        <div className="pt-24 text-center">
          <p className="text-neutral-400 text-sm">
            Noch keine Habits angelegt.
          </p>
          <p className="text-neutral-400 text-sm mt-1">
            Erstelle deinen ersten in den Einstellungen.
          </p>
        </div>
      )}
      {habits.map((h) => {
        const isDone = checked.has(h.id);
        return (
          <button
            key={h.id}
            aria-label={
              isDone
                ? `${h.name} rückgängig`
                : `${h.name} abgeschlossen`
            }
            className={`w-full flex items-center gap-4 py-3.5 px-4 rounded-2xl transition
              border
              ${isDone ? 'opacity-40' : 'opacity-100'}`}
            style={{
              backgroundColor: isDone
                ? h.color + '18'
                : '#fff',
              borderColor: isDone
                ? h.color + '33'
                : h.color + '18',
            }}
            onClick={() => toggle(h.id)}
          >
            <span
              className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0 transition"
              style={{
                backgroundColor: isDone
                  ? h.color + '33'
                  : h.color + '18',
                color: isDone ? h.color + '88' : h.color,
              }}
            >
              <IconCheck size={16} />
            </span>
            <span
              className="text-left text-[15px] flex-1"
              style={{
                fontWeight: 500,
                textDecoration: isDone ? 'line-through' : undefined,
              }}
            >
              {h.name}
            </span>
          </button>
        );
      })}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { IconPlus, IconPencil, IconTrash } from '../icons';
import {
  getHabits,
  addHabit,
  updateHabit,
  deleteHabit,
  getDarkMode,
  setDarkMode,
} from '../lib/db';
import type { Habit, DarkMode } from '../lib/types';

const PRESET_COLORS = [
  '#e74c3c',
  '#e67e22',
  '#f1c40f',
  '#2ecc71',
  '#1abc9c',
  '#3498db',
  '#9b59b6',
  '#6c5ce7',
  '#fd79a8',
];

const PRESET_ICONS = [
  '💧',
  '📖',
  '🏃',
  '🧘',
  '✍️',
  '🎨',
  '🎵',
  '🍳',
  '💊',
  '🧹',
  '🛁',
  '👟',
  '💪',
  '📷',
  '🧠',
  '💡',
];

export function Settings() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [darkMode, setDarkMode_1] = useState<DarkMode>('system');
  const [editing, setEditing] = useState<string | null>(null);
  const [editName, setEditName] = useState('');
  const [showForm, setShowForm] = useState(false);
  const [newName, setNewName] = useState('');
  const [newColor, setNewColor] = useState(PRESET_COLORS[0]);
  const [newIcon, setNewIcon] = useState(PRESET_ICONS[0]);
  const [removed, setRemoved] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      const h = await getHabits();
      const dm = await getDarkMode();
      setHabits(h);
      setDarkMode_(dm);
    })();
  }, []);

  async function handleCreate() {
    if (!newName.trim()) return;
    const id = await addHabit({
      name: newName.trim(),
      color: newColor,
      icon: newIcon,
    });
    setHabits((prev) => [...prev, { id, name: newName.trim(), color: newColor, icon: newIcon, createdAt: Date.now() }]);
    setShowForm(false);
    setNewName('');
  }

  async function handleEdit(habitId: string) {
    const habit = habits.find((h) => h.id === habitId);
    if (!habit) return;
    await updateHabit(habitId, { name: editName.trim(), color: newColor, icon: newIcon });
    setHabits((prev) =>
      prev.map((h) =>
        h.id === habitId ? { ...h, name: editName.trim(), color: newColor, icon: newIcon } : h
      )
    );
    setEditing(null);
  }

  async function handleDelete(habitId: string) {
    await deleteHabit(habitId);
    setHabits((prev) => prev.filter((h) => h.id !== habitId));
  }

  async function toggleDarkMode() {
    const next: DarkMode =
      darkMode === 'system' ? 'light' : darkMode === 'light' ? 'dark' : 'system';
    await setDarkMode_(next);
    await (await import('../lib/db')).setDarkMode(next);
  }

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <h2 className="text-base mb-5">Einstellungen</h2>

      {/* Dark mode */}
      <div className="mb-8">
        <h3 className="text-xs uppercase tracking-[0.08em] text-neutral-500 mb-2">
          Anzeige
        </h3>
        <button
          onClick={toggleDarkMode}
          className="px-4 py-3 rounded-xl text-left text-[15px] w-full"
          style={{
            backgroundColor: '#fff',
            border: '1px solid #e7e5e4',
          }}
        >
          {darkMode === 'system'
            ? 'System-Richtlinien folgen'
            : darkMode === 'light'
            ? 'Heller Modus'
            : 'Dunkler Modus'}
        </button>
      </div>

      {/* Habits list */}
      <div className="mb-6">
        <h3 className="text-xs uppercase tracking-[0.08em] text-neutral-500 mb-2">
          Meine Habits
        </h3>
        {habits.length === 0 ? (
          <p className="text-sm text-neutral-400">
            Erstelle deinen ersten Habit.
          </p>
        ) : (
          <div className="space-y-2">
            {habits.map((h) => (
              <div
                key={h.id}
