import { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid } from 'recharts';
import {
  getHabits,
  getChecksForDate,
  lastXDays,
  getMoodEntry,
} from '../lib/db';
import { calcDailyStats } from '../lib/streaks';
import type { Habit, MoodEntry } from '../lib/types';
import { moodEmoji, moodLabel } from '../lib/mood';

export function Week() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [data, setData] = useState<Record<string, number>>({});
  const [moods, setMoods] = useState<Record<string, MoodEntry>>({});
  const days = lastXDays(7);
  const labels = days.map((d) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-DE', { weekday: 'short' }).charAt(0);
  });

  useEffect(() => {
    (async () => {
      const h = await getHabits();
      const checks = await Promise.all(
        days.map((d) => getChecksForDate(d))
      );
      const counts = calcDailyStats(
        checks.flatMap((ids, i) =>
          ids.map((hId) => ({ habitId: hId, date: days[i] }))
        )
      );
      const moodEntries = await Promise.all(
        days.map((d) => getMoodEntry(d))
      );
      setHabits(h);
      setData(counts);
      setMoods(
        Object.fromEntries(
          moodEntries.filter(Boolean).map((m) => [m!.date, m!])
        )
      );
    })();
  }, []);

  const chartData = days.map((d) => ({
    label: labels[days.indexOf(d)],
    date: d,
    checked: data[d] || 0,
    mood: moods[d]?.mood,
  }));

  const maxChecked = habits.length > 0 ? habits.length : 3;
  const totalChecked = chartData.reduce(
    (s, d) => s + d.checked,
    0
  );
  const avgMood =
    Object.values(moods).length > 0
      ? Object.values(moods).reduce(
          (s, m) => s + m.mood,
          0
        ) / Object.values(moods).length
      : 0;

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <h2 className="text-base mb-4">Wochenübersicht</h2>

      <div className="mb-6">
        <div className="flex justify-between text-[13px] text-neutral-500 mb-3">
          <span>{totalChecked} abgehakt</span>
          {avgMood > 0 && (
            <span className="text-neutral-600">
              {moodEmoji(Math.round(avgMood))} {moodLabel(Math.round(avgMood) as 5)}
            </span>
          )}
        </div>
        <div style={{ height: 180 }} className="px-1">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} barGap={4}>
              <XAxis
                dataKey="label"
                axisLine={false}
                tick={{ fontSize: 12, fill: '#78716c' }}
              />
              <YAxis
                axisLine={false}
                tick={false}
                domain={[0, maxChecked]}
              />
              <Tooltip
                content={({ active, payload }) => {
                  if (!active || !payload?.[0]) return null;
                  const p = payload[0].payload;
                  return (
                    <div
                      style={{
                        padding: '8px 12px',
                        fontSize: 13,
                        backgroundColor: '#fff',
                        border: '1px solid #e7e5e4',
                        borderRadius: 8,
                      }}
                    >
                      <p>{p.label} — {p.checked} erledigt</p>
                      {p.mood && (
                        <p className="text-neutral-500">
                          {moodEmoji(p.mood)} {moodLabel(p.mood)}
                        </p>
                      )}
                    </div>
                  );
                }}
              />
              <Bar
                dataKey="checked"
                radius={[6, 6, 0, 0]}
                fill="#1c1917"
              />
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {habits.length > 0 && Object.keys(moods).length > 0 && (
        <div className="mb-6">
          <h3 className="text-xs uppercase tracking-[0.08em] text-neutral-500 mb-2">
            Stimmungen
          </h3>
          <div className="flex gap-3 flex-wrap">
            {days
              .filter((d) => moods[d])
              .map((d) => {
                const m = moods[d]!;
                return (
                  <span
                    key={d}
                    title={m.note}
                    className="text-lg"
                  >
                    {moodEmoji(m.mood)}
                  </span>
                );
              })}
          </div>
        </div>
      )}
    </div>
  );
}

