import { useState, useEffect } from 'react';
import {
  getHabits,
  getChecksForDate,
  getMoodEntry,
  checkHabit,
  uncheckHabit,
  today,
  formatDate,
} from '../lib/db';
import type { Habit, MoodValue, MoodEntry } from '../lib/types';
import { IconCheck } from '../icons';
import { MOOD_EMOJIS, moodLabel } from '../lib/mood';
import { calcStreak } from '../lib/streaks';

function DayBadge({ habit, checkHabitId, checks }: {
  habit: Habit;
  checkHabitId: string;
  checks: Array<{ habitId: string; date: string }>;
}) {
  const streak = calcStreak(checks, habit.id);
  const isDone = checkHabitId === habit.id;

  return (
    <div
      className="mb-2.5"
      style={{
        backgroundColor: isDone
          ? habit.color + '14'
          : '#fff',
        border: `1px solid ${isDone ? habit.color + '28' : '#e7e5e4'}`,
      }}
    >
      <button
        onClick={() => (checked && checked.has(habit.id)
          ? checked.delete(habit.id)
          : checked && checked.add(habit.id)) && toggle(habit.id)}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 12,
          padding: '11px 14px',
          width: '100%',
          cursor: 'pointer',
          background: 'transparent',
          outline: 'none',
          color: isDone ? habit.color + '88' : habit.color,
        }}
        aria-label={`${isDone ? `${habit.name} rückgängig` : `${habit.name} abgeschlossen`}`}
      >
        {/* badge */}
        <div
          className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0 transition"
          style={{
            backgroundColor: isDone
              ? habit.color
              : habit.color + '14',
            color: isDone ? '#fff' : habit.color,
          }}
        >
          <IconCheck size={15} />
        </div>
        <div className="flex-1 min-w-0">
          <p className="text-[14px] leading-tight" style={{
            fontWeight: 500,
            textDecoration: isDone ? 'line-through' : undefined,
          }}>
            {habit.name}
          </p>
          {streak.current > 1 && (
            <p className="text-[11px] mt-1" style={{ color: habit.color }}>
              {streak.current}x {streak.longest > streak.current ? `/ ${streak.longest}` : ''}
            </p>
          )}
        </div>
      </button>
    </div>
  );
}

