export function Today() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [checks, setChecks] = useState<Array<{ habitId: string; date: string }>>([]);
  const [moodEntry, setMoodEntry] = useState<MoodEntry | undefined>();
  const date = today();

  useEffect(() => {
    (async () => {
      const h = await getHabits();
      const c = await Promise.all([
        getChecksForDate(date),
        getMoodEntry(date),
      ]);
      setHabits(h);
      setChecks(c[0] as Array<{ habitId: string; date: string }>);
      setMoodEntry(c[1]);
    })();
  }, [date]);

  const done = checks.filter((c) => c.date === date).length;

  async function toggle(id: string) {
    const was = checks.some((c) => c.habitId === id && c.date === date);
    const next = [...checks];
    if (was) {
      await uncheckHabit(id, date);
    } else {
      await checkHabit(id, date);
    }
    const refreshed = await getChecksForDate(date);
    setChecks(refreshed);
  }

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <p className="text-[12px] uppercase tracking-[0.08em] font-medium text-neutral-500 mb-1">
        {formatDate(new Date(date))}
      </p>
      {habits.length > 0 && (
        <p className="text-[12px] text-neutral-500 mb-4">
          {done} von {habits.length} erledigt
        </p>
      )}
      {habits.length === 0 ? (
        <div className="pt-16 text-center">
          <p className="text-neutral-400 text-[14px]">
            Noch keine Habits angelegt.
          </p>
          <p className="text-neutral-400 text-[14px] mt-1">
            Erstelle deinen ersten in den Einstellungen.
          </p>
        </div>
      ) : (
        habits.map((h) => (
          <DayBadge
            key={h.id}
            habit={h}
            checkHabitId={checks.find(
              (c) => c.habitId === h.id && c.date === date
            )?.habitId ?? ''}
            checks={checks}
          />
        ))
      )}

      {/* mood */}
      {habits.length > 0 && (
        <div className="mt-5">
          <p className="text-[12px] uppercase tracking-[0.08em] text-neutral-500 mb-2">
            Stimmung
          </p>
          <MoodPicker entry={moodEntry} />
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import {
  getHabits,
  getChecksForDate,
  getMoodEntry,
  checkHabit,
  uncheckHabit,
  today,
  formatDate,
  getHabits as loadHabits,
  getChecksForDate as loadChecks,
  getMoodEntry as loadMood,
} from '../lib/db';
import type { Habit, MoodValue, MoodEntry } from '../lib/types';
import { IconCheck } from '../icons';
import { MOOD_EMOJIS, moodLabel } from '../lib/mood';
import { calcStreak } from '../lib/streaks';

export function Today() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [todayChecks, setTodayChecks] = useState<string[]>([]);
  const [checks, setChecks] = useState<Array<{ habitId: string; date: string }>>([]);
  const [moodEntry, setMoodEntry] = useState<MoodEntry | undefined>();
  const date = today();
  const done = todayChecks.length;

  useEffect(() => {
    (async () => {
      const h = await loadHabits();
      const c = await loadChecks(date);
      const m = await loadMood(date);
      setHabits(h);
      setTodayChecks(c.map((e) => e.habitId));
      setChecks(c);
      setMoodEntry(m);
    })();
  }, [date]);

  async function toggle(id: string) {
    const was = todayChecks.includes(id);
    if (was) {
      await uncheckHabit(id, date);
    } else {
      await checkHabit(id, date);
    }
    const updated = await loadChecks(date);
    setTodayChecks(updated.map((e) => e.habitId));
  }

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <p className="text-[12px] uppercase tracking-[0.08em] font-medium text-neutral-500 mb-1">
        {formatDate(new Date(date))}
      </p>
      {habits.length > 0 && (
        <p className="text-[12px] text-neutral-500 mb-4">
          {done} von {habits.length} erledigt
        </p>
      )}
      {habits.length === 0 ? (
        <div className="pt-16 text-center">
          <p className="text-neutral-400 text-[14px]">
            Noch keine Habits angelegt.
          </p>
          <p className="text-neutral-400 text-[14px] mt-1">
            Erstelle deinen ersten in den Einstellungen.
          </p>
        </div>
      ) : (
        habits.map((h) => {
          const isDone = todayChecks.includes(h.id);
          const streak = calcStreak(checks, h.id);

          return (
            <button
              key={h.id}
              onClick={() => toggle(h.id)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 12,
                padding: '12px 14px',
                width: '100%',
                cursor: 'pointer',
                marginBottom: 10,
                borderRadius: 16,
                backgroundColor: isDone ? h.color + '12' : '#fff',
                border: `1px solid ${isDone ? h.color + '28' : '#e7e5e4'}`,
                color: isDone ? h.color + '77' : undefined,
                outline: 'none',
              }}
              aria-label={`${isDone ? `${h.name} rückgängig` : `${h.name} abgeschlossen`}`}
            >
              <span
                className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0 transition"
                style={{
                  backgroundColor: isDone ? h.color : h.color + '12',
                  color: isDone ? '#fff' : h.color,
                }}
              >
                <IconCheck size={15} />
              </span>
              <div className="flex-1 min-w-0 text-left">
                <p className="text-[14px]" style={{
                  fontWeight: 500,
                  textDecoration: isDone ? 'line-through' : undefined,
                }}>
                  {h.name}
                </p>
                {streak.current > 1 && (
                  <p className="text-[11px] mt-1" style={{ color: h.color }}>
                    {streak.current}x {streak.longest > streak.current ? `/ ${streak.longest}` : ''}
                  </p>
                )}
              </div>
            </button>
          );
        })
      )}

      {/* mood */}
      {habits.length > 0 && (
        <div className="mt-5">
          <p className="text-[12px] uppercase tracking-[0.08em] text-neutral-500 mb-2">
            Stimmung
          </p>
          <div className="flex justify-center gap-3">
            {(Object.keys(MOOD_EMOJIS) as MoodValue[]).map((v) => (
              <button
                key={v}
                onClick={async () => {
                  const { saveMoodEntry } = await import('../lib/db');
                  await saveMoodEntry(v, '');
                  setMoodEntry(await loadMood(date));
                }}
                className="w-11 h-11 rounded-xl flex items-center justify-center text-xl transition active:scale-95"
                style={{
                  backgroundColor: moodEntry?.mood === v ? '#f5f5f4' : '#fff',
                  border: moodEntry?.mood === v ? '1px solid #d6d3d1' : '1px solid transparent',
                }}
                aria-label={moodLabel(v)}
              >
                {MOOD_EMOJIS[v]}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import {
  getHabits,
  lastXDays,
  getMoodEntry,
  today,
  getChecksForDate,
} from '../lib/db';
import { MOOD_EMOJIS, moodLabel } from '../lib/mood';
import { calcDailyStats } from '../lib/streaks';
import type { Habit, MoodEntry } from '../lib/types';

export function Week() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [data, setData] = useState<Record<string, number>>({});
  const [moods, setMoods] = useState<Record<string, MoodEntry>>({});
  const days = lastXDays(7);
  const labels = days.map((d) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-DE', { weekday: 'short' }).charAt(0).toUpperCase();
  });

  useEffect(() => {
    (async () => {
      const h = await getHabits();
      const checksByDay = await Promise.all(
        days.map((d) => getChecksForDate(d))
      );
      const counts = calcDailyStats(
        checksByDay.flatMap((ids, i) =>
          ids.map((habId) => ({ habitId: habId, date: days[i] }))
        )
      );
      const moodEntries = await Promise.all(
        days.map((d) => getMoodEntry(d))
      );
      setHabits(h);
      setData(counts);
      setMoods(
        Object.fromEntries(
          moodEntries.filter(Boolean).map((m) => [m!.date, m!])
        )
      );
    })();
  }, []);

  const chartData = days.map((d) => ({
    label: labels[days.indexOf(d)],
    date: d,
    checked: data[d] || 0,
    mood: moods[d]?.mood,
  }));

  const maxChecked = habits.length > 0 ? habits.length : 3;
  const totalChecked = chartData.reduce((s, d) => s + d.checked, 0);
  const moodEntries = Object.values(moods);
  const avgMood =
    moodEntries.length > 0
      ? moodEntries.reduce((s, m) => s + m.mood, 0) / moodEntries.length
      : 0;

  const todayStr = today();

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <h2 className="text-base mb-4">Wochenübersicht</h2>

      <div className="mb-3">
        <div className="flex justify-between text-[12px] text-neutral-500 mb-3">
          <span>{totalChecked} abgehakt</span>
          {avgMood > 0 && (
            <span className="text-neutral-600">
              {MOOD_EMOJIS[Math.round(avgMood)]} {moodLabel(Math.round(avgMood) as 5)}
            </span>
          )}
        </div>
        <div style={{ height: 170 }} className="px-1">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} barGap={4}>
              <XAxis
                dataKey="label"
                axisLine={false}
                tick={{ fontSize: 11, fill: '#78716c' }}
              />
              <YAxis
                axisLine={false}
                tick={false}
                domain={[0, maxChecked]}
              />
              <Tooltip
                content={({ active, payload }) => {
                  if (!active || !payload?.[0]) return null;
                  const p = (payload[0].payload as typeof chartData[number]);
                  return (
                    <div
                      style={{
                        padding: '8px 12px',
                        fontSize: 13,
                        backgroundColor: '#fff',
                        border: '1px solid #e7e5e4',
                        borderRadius: 8,
                      }}
                    >
                      <p style={{ fontWeight: 500 }}>{p.label} — {p.checked} erledigt</p>
                      {p.mood && (
                        <p className="text-neutral-500">
                          {MOOD_EMOJIS[p.mood]} {moodLabel(p.mood)}
                        </p>
                      )}
                    </div>
                  );
                }}
              />
              <Bar
                dataKey="checked"
                radius={[6, 6, 0, 0]}
              >
                {chartData.map((entry, i) => (
                  <Cell
                    key={entry.date}
                    fill={entry.date === todayStr ? '#4a6fa5' : '#1c1917'}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {Object.keys(moods).length > 0 && (
        <div className="mb-5">
          <p className="text-[12px] uppercase tracking-[0.08em] text-neutral-500 mb-2">
            Stimmungen
          </p>
          <div className="flex gap-3 flex-wrap">
            {days
              .filter((d) => moods[d])
              .map((d) => {
                const m = moods[d]!;
                return (
                  <span
                    key={d}
                    title={m.note || moodLabel(m.mood)}
                    className="text-lg"
                  >
                    {MOOD_EMOJIS[m.mood]}
                  </span>
                );
              })}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import type { DarkMode } from './lib/types';
import { getDarkMode, getHabits, getChecksForDate, today } from './lib/db';
import { Today } from './components/Today';
import { Week } from './components/Week';
import { Settings } from './components/Settings';
import { IconCalendar, IconChart, IconSettings } from './icons';

type Tab = 'today' | 'week' | 'settings';

export default function App() {
  const [tab, setTab] = useState<Tab>('today');
  const [darkMode, setDarkModeState] = useState<DarkMode>('system');

  useEffect(() => {
    (async () => {
      const dm = await getDarkMode();
      setDarkModeState(dm);
    })();
  }, []);

  useEffect(() => {
    document.body.style.background =
      darkMode === 'dark' ? '#1a1a1a' : darkMode === 'light' ? '#fff' : '';
  }, [darkMode]);

  return (
    <div className="min-h-[100dvh] flex flex-col">
      {tab === 'today' && <Today />}
      {tab === 'week' && <Week />}
      {tab === 'settings' && <Settings />}

      <nav
        className="fixed bottom-0 left-0 right-0 flex justify-center"
        style={{
          borderTop: '1px solid #e7e5e4',
          background: darkMode === 'dark' ? '#1a1a1a' : '#fff',
          height: 68,
        }}
      >
        <div className="flex gap-0">
          <TabButton
            label="Heute"
            icon={<IconCalendar size={20} />}
            active={tab === 'today'}
            onClick={() => setTab('today')}
          />
          <TabButton
            label="Woche"
            icon={<IconChart size={20} />}
            active={tab === 'week'}
            onClick={() => setTab('week')}
          />
          <TabButton
            label="Einstellungen"
            icon={<IconSettings size={20} />}
            active={tab === 'settings'}
            onClick={() => setTab('settings')}
          />
        </div>
      </nav>
    </div>
  );
}

function TabButton({
  label,
  icon,
  active,
  onClick,
}: {
  label: string;
  icon: React.ReactNode;
  active: boolean;
  onClick: () => void;
}) {
  return (
    <button
      onClick={onClick}
      className="flex-1 flex flex-col items-center justify-center gap-1"
      style={{
        color: active ? '#1c1917' : '#78716c',
      }}
    >
      <span
        style={{
          width: 28,
          height: 28,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        {icon}
      </span>
      <span style={{ fontSize: 11, fontWeight: 500 }}>{label}</span>
    </button>
  );
}

