import { useState, useEffect } from 'react';
import {
  getHabits as loadHabits,
  getChecksForDate as loadChecks,
  getMoodEntry as loadMood,
  checkHabit,
  uncheckHabit,
  saveMoodEntry,
  today,
  formatDate,
} from '../lib/db';
import type { Habit, MoodValue, MoodEntry } from '../lib/types';
import { IconCheck } from '../icons';
import { MOOD_EMOJIS, moodLabel } from '../lib/mood';
import { calcStreak } from '../lib/streaks';

export function Today() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [todayChecks, setTodayChecks] = useState<string[]>([]);
  const [checks, setChecks] = useState<Array<{ habitId: string; date: string }>>([]);
  const [moodEntry, setMoodEntry] = useState<MoodEntry | undefined>();
  const date = today();
  const done = todayChecks.length;

  useEffect(() => {
    (async () => {
      const h = await loadHabits();
      const c = await loadChecks(date);
      const m = await loadMood(date);
      setHabits(h);
      setTodayChecks(c.map((e) => e.habitId));
      setChecks(c);
      setMoodEntry(m);
    })();
  }, [date]);

  async function toggle(id: string) {
    const was = todayChecks.includes(id);
    if (was) {
      await uncheckHabit(id, date);
    } else {
      await checkHabit(id, date);
    }
    const updated = await loadChecks(date);
    setTodayChecks(updated.map((e) => e.habitId));
  }

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <p className="text-[12px] uppercase tracking-[0.08em] font-medium text-neutral-500 mb-1">
        {formatDate(new Date(date))}
      </p>
      {habits.length > 0 && (
        <p className="text-[12px] text-neutral-500 mb-4">
          {done} von {habits.length} erledigt
        </p>
      )}
      {habits.length === 0 ? (
        <div className="pt-16 text-center">
          <p className="text-neutral-400 text-[14px]">
            Noch keine Habits angelegt.
          </p>
          <p className="text-neutral-400 text-[14px] mt-1">
            Erstelle deinen ersten in den Einstellungen.
          </p>
        </div>
      ) : (
        habits.map((h) => {
          const isDone = todayChecks.includes(h.id);
          const streak = calcStreak(checks, h.id);

          return (
            <button
              key={h.id}
              onClick={() => toggle(h.id)}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 12,
                padding: '12px 14px',
                width: '100%',
                cursor: 'pointer',
                marginBottom: 10,
                borderRadius: 16,
                backgroundColor: isDone ? h.color + '12' : '#fff',
                border: `1px solid ${isDone ? h.color + '28' : '#e7e5e4'}`,
                color: isDone ? h.color + '77' : undefined,
                outline: 'none',
              }}
              aria-label={`${isDone ? `${h.name} rückgängig` : `${h.name} abgeschlossen`}`}
            >
              <span
                className="w-7 h-7 rounded-lg flex items-center justify-center shrink-0 transition"
                style={{
                  backgroundColor: isDone ? h.color : h.color + '12',
                  color: isDone ? '#fff' : h.color,
                }}
              >
                <IconCheck size={15} />
              </span>
              <div className="flex-1 min-w-0 text-left">
                <p className="text-[14px]" style={{
                  fontWeight: 500,
                  textDecoration: isDone ? 'line-through' : undefined,
                }}>
                  {h.name}
                </p>
                {streak.current > 1 && (
                  <p className="text-[11px] mt-1" style={{ color: h.color }}>
                    {streak.current}x {streak.longest > streak.current ? `/ ${streak.longest}` : ''}
                  </p>
                )}
              </div>
            </button>
          );
        })
      )}

      {/* mood */}
      {habits.length > 0 && (
        <div className="mt-5">
          <p className="text-[12px] uppercase tracking-[0.08em] text-neutral-500 mb-2">
            Stimmung
          </p>
          <div className="flex justify-center gap-3">
            {(Object.keys(MOOD_EMOJIS) as (keyof typeof MOOD_EMOJIS)[]).map((v) => (
              <button
                key={v}
                onClick={async () => {
                  await saveMoodEntry(Number(v) as MoodValue, '');
                  setMoodEntry(await loadMood(date));
                }}
                className="w-11 h-11 rounded-xl flex items-center justify-center text-xl transition active:scale-95"
                style={{
                  backgroundColor: moodEntry?.mood === Number(v) ? '#f5f5f4' : '#fff',
                  border: moodEntry?.mood === Number(v) ? '1px solid #d6d3d1' : '1px solid transparent',
                }}
                aria-label={moodLabel(Number(v) as MoodValue)}
              >
                {MOOD_EMOJIS[Number(v) as MoodValue]}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import { useState, useEffect } from 'react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';
import {
  lastXDays,
  getMoodEntry,
  today,
  getChecksForDate,
  getHabits,
} from '../lib/db';
import { MOOD_EMOJIS, moodLabel } from '../lib/mood';
import { calcDailyStats } from '../lib/streaks';
import type { Habit, MoodEntry } from '../lib/types';

export function Week() {
  const [habits, setHabits] = useState<Habit[]>([]);
  const [data, setData] = useState<Record<string, number>>({});
  const [moods, setMoods] = useState<Record<string, MoodEntry>>({});
  const days = lastXDays(7);
  const labels = days.map((d) => {
    const date = new Date(d + 'T00:00:00');
    return date.toLocaleDateString('de-DE', { weekday: 'short' }).charAt(0).toUpperCase();
  });

  useEffect(() => {
    (async () => {
      const h = await getHabits();
      const checksByDay = await Promise.all(
        days.map((d) => getChecksForDate(d))
      );
      const counts = calcDailyStats(
        checksByDay.flatMap((ids: Array<{habitId: string; date: string}>, i: number) =>
          ids.map((habId: {habitId: string}) => ({ habitId: habId.habitId, date: days[i] }))
        )
      );
      const moodEntries = await Promise.all(
        days.map((d) => getMoodEntry(d))
      );
      setHabits(h);
      setData(counts);
      setMoods(
        Object.fromEntries(
          moodEntries.filter(Boolean).map((m) => [m!.date, m!])
        )
      );
    })();
  }, []);

  const chartData = days.map((d) => ({
    label: labels[days.indexOf(d)],
    date: d,
    checked: data[d] || 0,
    mood: moods[d]?.mood,
  }));

  const maxChecked = habits.length > 0 ? habits.length : 3;
  const totalChecked = chartData.reduce((s, d) => s + d.checked, 0);
  const moodEntries = Object.values(moods);
  const avgMood =
    moodEntries.length > 0
      ? moodEntries.reduce((s, m) => s + m.mood, 0) / moodEntries.length
      : 0;

  const todayStr = today();

  return (
    <div className="max-w-md mx-auto px-5 py-6">
      <h2 className="text-base mb-4">Wochenübersicht</h2>

      <div className="mb-3">
        <div className="flex justify-between text-[12px] text-neutral-500 mb-3">
          <span>{totalChecked} abgehakt</span>
          {avgMood > 0 && (
            <span className="text-neutral-600">
              {MOOD_EMOJIS[Math.round(avgMood) as 5]} {moodLabel(Math.round(avgMood) as 5)}
            </span>
          )}
        </div>
        <div style={{ height: 170 }} className="px-1">
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={chartData} barGap={4}>
              <XAxis
                dataKey="label"
                axisLine={false}
                tick={{ fontSize: 11, fill: '#78716c' }}
              />
              <YAxis
                axisLine={false}
                tick={false}
                domain={[0, maxChecked]}
              />
              <Tooltip
                content={({ active, payload }) => {
                  if (!active || !payload?.[0]) return null;
                  const p = (payload[0].payload as typeof chartData[number]);
                  return (
                    <div
                      style={{
                        padding: '8px 12px',
                        fontSize: 13,
                        backgroundColor: '#fff',
                        border: '1px solid #e7e5e4',
                        borderRadius: 8,
                      }}
                    >
                      <p style={{ fontWeight: 500 }}>{p.label} — {p.checked} erledigt</p>
                      {p.mood && (
                        <p className="text-neutral-500">
                          {MOOD_EMOJIS[p.mood]} {moodLabel(p.mood)}
                        </p>
                      )}
                    </div>
                  );
                }}
              />
              <Bar
                dataKey="checked"
                radius={[6, 6, 0, 0]}
              >
                {chartData.map((entry) => (
                  <Cell
                    key={entry.date}
                    fill={entry.date === todayStr ? '#4a6fa5' : '#1c1917'}
                  />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>

      {Object.keys(moods).length > 0 && (
        <div className="mb-5">
          <p className="text-[12px] uppercase tracking-[0.08em] text-neutral-500 mb-2">
            Stimmungen
          </p>
          <div className="flex gap-3 flex-wrap">
            {days
              .filter((d) => moods[d])
              .map((d) => {
                const m = moods[d]!;
                return (
                  <span
                    key={d}
                    title={m.note || moodLabel(m.mood)}
                    className="text-lg"
                  >
                    {MOOD_EMOJIS[m.mood]}
                  </span>
                );
              })}
          </div>
        </div>
      )}
    </div>
  );
}

import type { IDBPDatabase, OpenDBCallbacks } from 'idb';
import type {
  Habit,
  MoodEntry,
  DarkMode,
} from './types';

const DB_NAME = 'rhythm';
const DB_VERSION = 1;

let dbPromise: Promise<IDBPDatabase> | null = null;

function getDb() {
  if (!dbPromise) {
    const callbacks: OpenDBCallbacks = {
      upgrade: (db) => {
        if (!db.objectStoreNames.contains('habits')) {
          const hs = db.createObjectStore('habits', {
            keyPath: 'id',
          });
          hs.createIndex('createdAt', 'createdAt');
        }
        if (!db.objectStoreNames.contains('checks')) {
          const cs = db.createObjectStore('checks', {
            keyPath: 'id',
          });
          cs.createIndex('date', 'date');
          cs.createIndex('habitId', 'habitId');
        }
        if (!db.objectStoreNames.contains('mood')) {
          const ms = db.createObjectStore('mood', {
            keyPath: 'id',
          });
          ms.createIndex('date', 'date');
        }
        if (!db.objectStoreNames.contains('settings')) {
          db.createObjectStore('settings', {
            keyPath: 'key',
          });
        }
      },
    };
    dbPromise = openDB(DB_NAME, DB_VERSION, callbacks);
  }
  return dbPromise;
}

/* ── Habits ──────────────────────────────── */

export async function getHabits() {
  const db = await getDb();
  const tx = db.transaction('habits', 'readonly');
  return tx.store.getAll();
}

export async function addHabit(
  habit: Omit<Habit, 'id' | 'createdAt'>
): Promise<string> {
  const id = crypto.randomUUID();
  const now = Date.now();
  const db = await getDb();
  const tx = db.transaction('habits', 'readwrite');
  await tx.store.add({ ...habit, id, createdAt: now });
  await tx.done;
  return id;
}

export async function updateHabit(id: string, patch: Partial<Pick<Habit, 'name' | 'color' | 'icon'>>): Promise<void> {
  const db = await getDb();
  const tx = db.transaction('habits', 'readwrite');
  const record = await tx.store.get(id);
  if (record) {
    Object.assign(record, patch);
    await tx.store.put(record);
  }
  await tx.done;
}

export async function deleteHabit(id: string) {
  const db = await getDb();
  const tx = db.transaction(
    ['habits', 'checks'],
    'readwrite'
  );
  await tx.store('habits').delete(id);
  const checks = await tx.store('checks').getAll();
  for (const c of checks) {
    if (c.habitId === id) {
      await tx.store('checks').delete(c.id);
    }
  }
  await tx.done;
}

/* ── Checks ──────────────────────────────── */

export async function checkHabit(
  habitId: string,
  date: string
) {
  const db = await getDb();
  const tx = db.transaction('checks', 'readwrite');
  const key = `${date}:${habitId}`;
  await tx.store.put({ id: key, habitId, date });
  await tx.done;
}

export async function uncheckHabit(
  habitId: string,
  date: string
) {
  const db = await getDb();
  const tx = db.transaction('checks', 'readwrite');
  await tx.store.delete(`${date}:${habitId}`);
  await tx.done;
}

export async function getChecksForDate(date: string) {
  const db = await getDb();
  const tx = db.transaction('checks', 'readonly');
  const all = await tx.store.index('date').getAll(date);
  return all;
}

/* ── Mood ────────────────────────────────── */

export async function saveMoodEntry(
  mood: MoodEntry['mood'],
  note: string
): Promise<string> {
  const date = today();
  const db = await getDb();
  const tx = db.transaction('mood', 'readwrite');
  // First delete any existing entry for this date
  const existing = await tx.store.index('date').get(date);
  if (existing) {
    await tx.store.delete(existing.id);
  }
  const id = `${date}:mood`;
  await tx.store.add({ id, date, mood, note });
  await tx.done;
  return id;
}

export async function getMoodEntry(date: string) {
  const db = await getDb();
  const tx = db.transaction('mood', 'readonly');
  return tx.store.index('date').get(date);
}

/* ── Settings ──────────────────────────────── */

export async function getDarkMode(): Promise<DarkMode> {
  const db = await getDb();
  const tx = db.transaction('settings', 'readonly');
  const record = await tx.store.get('darkMode');
  return record?.value ?? 'system';
}

export async function setDarkMode(mode: DarkMode) {
  const db = await getDb();
  const tx = db.transaction('settings', 'readwrite');
  await tx.store.put({ key: 'darkMode', value: mode });
  await tx.done;
}

/* ── Helpers ──────────────────────────────── */

export function today(): string {
  return new Date().toISOString().slice(0, 10);
}

export function formatDate(date: Date): string {
  return date.toLocaleDateString('de-DE', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
  });
}

export function lastXDays(n: number): string[] {
  return Array.from({ length: n }, (_, i) =>
    daysAgo(i)
  );
}

export function daysAgo(offset: number): string {
  const d = new Date(Date.now() - offset * 86400000);
  return d.toISOString().slice(0, 10);
}

export function isToday(date: string): boolean {
  return date === today();
}

import { lastXDays, daysAgo } from './db';

interface StreakResult {
  current: number;
  longest: number;
}

/* Look back from today, counting consecutively checked days.
 * Returns current streak and longest streak. */
export function calcStreak(
  checks: Array<{ habitId: string; date: string }>,
  habitId: string
): StreakResult {
  const habitChecks = checks
    .filter((c) => c.habitId === habitId)
    .map((c) => c.date)
    .sort();

  let current = 0;
  let longest = 0;

  for (const d of habitChecks) {
    const daysSince = diffDays(d);
    if (daysSince === current + 1 || (current === 0 && daysSince === 0)) {
      if (current + 1 > longest) {
        longest = current + 1;
      }
      current++;
    } else {
      current = 0;
    }
  }

  return {
    current,
    longest,
  };
}

export function calcDailyStats(
  checks: Array<{ habitId: string; date: string }>
): Record<string, number> {
  const grouped: Record<string, number> = {};
  for (const c of checks) {
    grouped[c.date] = (grouped[c.date] || 0) + 1;
  }
  return grouped;
}

function diffDays(dateStr: string): number {
  const today = new Date(todayNormalized());
  const target = new Date(dateStr);
  const diff = (today.getTime() - target.getTime()) / 86400000;
  return Math.round(diff);
}

function todayNormalized(): string {
  return new Date().toISOString().slice(0, 10);
}

