function MoodPicker({
  entries,
  date,
  loadMood,
}: {
  entries: MoodEntry | undefined;
  date: string;
  loadMood: (d: string) => Promise<MoodEntry | null>;
}) {
  const [selected, setSelected] = useState<MoodValue | null>(
    entries ? entries.mood : null
  );
  const [note, setNote] = useState(entries ? entries.note : '');

  async function handleSave() {
    if (selected == null) return;
    await saveMoodEntry(selected, note);
    setEntries(await loadMood(date));
  }

  return (
    <div>
      <div className="flex justify-center gap-3">
        {([1, 2, 3, 4, 5] as MoodValue[]).map((v) => (
          <button
            key={v}
            onClick={() => setSelected(v)}
            className="w-11 h-11 rounded-xl flex items-center justify-center text-xl transition active:scale-95"
            style={{
              backgroundColor: selected === v ? '#f5f5f4' : '#fff',
              border: selected === v ? '1px solid #d6d3d1' : '1px solid transparent',
            }}
            aria-label={moodLabel(v)}
          >
            {MOOD_EMOJIS[v]}
          </button>
        ))}
      </div>
      {selected != null && (
        <p className="text-center text-[12px] text-neutral-500 mt-2">
          {moodLabel(selected)}
        </p>
      )}
      <textarea
        value={note}
        onChange={(e) => setNote(e.target.value)}
        placeholder="Optional eine Notiz..."
        className="w-full mt-3 px-3 py-2.5 rounded-xl text-[13px] resize-none outline-none"
        style={{ backgroundColor: '#fff', border: '1px solid #e7e5e4' }}
        rows={2}
      />
      <button
        onClick={handleSave}
        className="mt-3 w-full py-2.5 rounded-xl text-[14px] font-medium transition active:scale-98"
        style={{ backgroundColor: '#1c1917', color: '#fff' }}
      >
        Gespeichert
      </button>
    </div>
  );
}

